using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class WebSearchTool
{
    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles, URLs, and snippets.")]
    public static IReadOnlyList<SearchResult> SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
        Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

        var results = new List<SearchResult>
        {
            new($"Overview of {query}", $"https://example.com/{Uri.EscapeDataString(query)}/overview",
                $"A comprehensive overview covering the key aspects of {query}, including recent developments and expert analysis."),
            new($"{query} - Latest Research", $"https://research.example.org/{Uri.EscapeDataString(query)}",
                $"Recent peer-reviewed research findings on {query} published in 2026, highlighting breakthroughs and emerging trends."),
            new($"Practical Applications of {query}", $"https://applied.example.com/{Uri.EscapeDataString(query)}",
                $"Real-world applications and case studies demonstrating how {query} is being used in industry today."),
        };

        return results;
    }
}

public sealed record SearchResult(string Title, string Url, string Snippet);

using System.ComponentModel;

namespace ResearchAgent.Tools;

public sealed class NoteTakingTool
{
    private readonly List<ResearchNote> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("A short title summarizing the note")] string title,
        [Description("The detailed content of the note")] string content)
    {
        var note = new ResearchNote(title, content, DateTime.UtcNow);
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved: \"{title}\"");
        return $"Note saved successfully: \"{title}\" ({_notes.Count} total notes)";
    }

    [Description("Retrieves all saved research notes collected so far.")]
    public IReadOnlyList<ResearchNote> GetAllNotes()
    {
        Console.WriteLine($"  [Tool] Retrieving all notes ({_notes.Count} total)");
        return _notes.AsReadOnly();
    }
}

public sealed record ResearchNote(string Title, string Content, DateTime SavedAt);

