using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// Register the note-taking tool as a singleton so state persists across agent turns
builder.Services.AddSingleton<NoteTakingTool>();

// Register the chat client via MEAI abstraction (no FunctionInvocation middleware needed — ChatClientAgent adds it)
builder.Services.AddChatClient(chatBuilder =>
    chatBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18",
        builder.Configuration["AI:Endpoint"] is string endpoint ? new Uri(endpoint) : null,
        builder.Configuration["AI:ApiKey"]
            ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.")));

var host = builder.Build();

// Resolve services
var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteTool = host.Services.GetRequiredService<NoteTakingTool>();

// Build the tool collection
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetAllNotes),
};

// Prompt for research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var systemPrompt = """
    You are a research assistant agent. Your goal is to thoroughly research the topic provided by the user.

    Follow this workflow:
    1. Search the web for information on the topic using multiple relevant queries.
    2. Save important findings as notes using the note-taking tool.
    3. After gathering enough information, retrieve all your notes.
    4. Provide a comprehensive summary of your findings to the user.

    Be thorough but concise. Cite sources where possible.
    """;

// Create the ChatClientAgent with tools
var agent = new ChatClientAgent(
    chatClient,
    instructions: systemPrompt,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

// Configure run options with iteration limits and chat parameters
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

Console.WriteLine("Agent is working...\n");

// Run the agent with the user's research request
var response = await agent.RunAsync(
    $"Please research the following topic and provide a summary: {topic}",
    session: null,
    runOptions);

// Output the agent's response
foreach (var message in response.Messages)
{
    if (!string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine("\n✅ Research complete!");

