                    "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.")));

var host = builder.Build();

// Resolve services
var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteTool = host.Services.GetRequiredService<NoteTakingTool>();

// Build the tool collection
var tools = new AIToolCollection
{
    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetAllNotes),
};

// Prompt for research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// Set up the agent conversation
var systemPrompt = $"""
    You are a research assistant agent. Your goal is to thoroughly research the topic provided by the user.

    Follow this workflow:
    1. Search the web for information on the topic using multiple relevant queries.
    2. Save important findings as notes using the note-taking tool.
    3. After gathering enough information, retrieve all your notes.
    4. Provide a comprehensive summary of your findings to the user.

    Be thorough but concise. Cite sources where possible.
    """;

var chatHistory = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}"),
};

var options = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [.. tools],
};

// Run the agent with the ChatClientAgent from Microsoft.Agents.AI
var agent = new ChatClientAgent(chatClient, options);
var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

Console.WriteLine("Agent is working...\n");

await foreach (var message in agent.InvokeStreamingAsync(chatHistory, invokeOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n✅ Research complete!");

